from fixtures import Fixture, load_fixtures, ROWS
from search import fixtures_for, has_club

KEY = ROWS[0][0]
COUNT = sum(1 for k, _ in ROWS if k == KEY)


def test_upper_case_with_spaces():
    assert len(fixtures_for(list(load_fixtures()), " " + KEY.upper() + " ")) == COUNT


def test_stored_value_not_tidy():
    data = [Fixture("  Alpha", 1), Fixture("beta", 2), Fixture("ALPHA ", 3)]
    assert [x.goals for x in fixtures_for(data, "alpha")] == [1, 3]


def test_exact():
    assert len(fixtures_for(list(load_fixtures()), KEY)) == COUNT


def test_no_match():
    assert fixtures_for(list(load_fixtures()), "zzz") == [] and not has_club(list(load_fixtures()), "zzz")
